import pandas as pd

def clean(df):
    df = df.drop_duplicates()
    df['flipper_length_mm'] = pd.to_numeric(df['flipper_length_mm'], errors='coerce')
    df = df.dropna(subset=['flipper_length_mm'])
    allowed_islands = ['Biscoe', 'Dream', 'Torgersen']
    df = df[df['island'].isin(allowed_islands)]
    return df

def answer(df):
    species_avg = df.groupby('species')['flipper_length_mm'].mean().to_dict()
    overall_avg = df['flipper_length_mm'].mean()
    result = {**species_avg, 'all': overall_avg}
    return {k: v for k, v in result.items() if not pd.isna(v)}
